use hilog_rust::{debug, HiLogLabel, LogLevel, LogType};

static LOG_LABEL: HiLogLabel = HiLogLabel {
    log_type: LogType::LogCore,
    domain: 0xd003200,
    tag: "translate",
};
debug!(LOG_LABEL, "translate task id={}, path={}", @public(1001), @private("/data/test"));
let loggable = unsafe {
    hilog_rust::HiLogIsLoggable(LOG_LABEL.domain, b"translate�".as_ptr() as *const _, LogLevel::Debug as u32)
};
assert!(loggable || !loggable);

