use ipc::{status_result, IpcResult, IpcStatusCode};

fn convert_native_status(code: i32) -> IpcResult<i32> {
    status_result(code, 1001_i32)
}
let value = convert_native_status(0)?;
assert_eq!(value, 1001);
let err = convert_native_status(IpcStatusCode::Failed as i32).unwrap_err();
assert_eq!(err, IpcStatusCode::Failed);

