use ipc::parcel::{Deserialize, MsgParcel, Serialize};
use ipc::IpcResult;

struct TaskId(i32);
impl Serialize for TaskId {
    fn serialize(&self, parcel: &mut MsgParcel) -> IpcResult<()> {
        parcel.write(&self.0)
    }
}
impl Deserialize for TaskId {
    fn deserialize(parcel: &mut MsgParcel) -> IpcResult<Self> {
        Ok(TaskId(parcel.read()?))
    }
}
let mut parcel = MsgParcel::new();
parcel.write(&TaskId(1001))?;
let task = parcel.read::<TaskId>()?;
assert_eq!(task.0, 1001);

