use log::{debug, info, Level, LevelFilter, Metadata, Record};

let metadata = Metadata::builder()
    .level(Level::Info)
    .target("translate")
    .build();
let record = Record::builder()
    .args(format_args!("translated {} files", 3))
    .metadata(metadata.clone())
    .build();
assert_eq!(record.level(), Level::Info);
assert_eq!(Level::Debug.to_level_filter(), LevelFilter::Debug);
info!("{}", record.args());
debug!("metadata target={}", record.metadata().target());

