use ipc::parcel::MsgParcel;
use ipc::remote::{RemoteObj, RemoteStub};
use samgr::definition::DOWNLOAD_SERVICE_ID;
use samgr::manage::SystemAbilityManager;

struct RunCount;
const SERVICE_TOKEN: &str = "OHOS.Download.RequestServiceInterface";

impl RemoteStub for RunCount {
    fn on_remote_request(
        &self,
        _code: u32,
        data: &mut ipc::parcel::MsgParcel,
        _reply: &mut ipc::parcel::MsgParcel,
    ) -> i32 {
        let token = data.read_interface_token().unwrap();
        assert_eq!(token, "OHOS.Download.NotifyInterface");
        let run_count: i64 = data.read().unwrap();
        println!("Run count: {}", run_count);
        0
    }
}

fn main() {
    let download_server = loop {
        if let Some(download_server) =
            SystemAbilityManager::check_system_ability(DOWNLOAD_SERVICE_ID)
        {
            break download_server;
        }
        SystemAbilityManager::load_system_ability(DOWNLOAD_SERVICE_ID, 15000).unwrap();
        std::thread::sleep(std::time::Duration::from_secs(1));
    };
    let mut data = MsgParcel::new();
    data.write_interface_token(SERVICE_TOKEN).unwrap();
    data.write_remote(RemoteObj::from_stub(RunCount).unwrap()).unwrap();
    download_server.send_request(16, &mut data).unwrap();
}

impl RemoteStub for RequestServiceStub {
    fn on_remote_request(&self, code: u32, data: &mut MsgParcel, reply: &mut MsgParcel) -> i32 {
        self.sa_handler.cancel_idle();
        self.active_counter.increment();
        const SERVICE_TOKEN: &str = "OHOS.Download.RequestServiceInterface";

        match data.read_interface_token() {
            Ok(token) if token == SERVICE_TOKEN => {}
            _ => {
                self.active_counter.decrement();
                return IpcStatusCode::Failed as i32;
            }
        };

        let res = match code {
            interface::CONSTRUCT => self.construct(data, reply),
            interface::PAUSE => self.pause(data, reply),
            interface::QUERY => self.query(data, reply),
            interface::START => self.start(data, reply),
            interface::STOP => self.stop(data, reply),
            interface::SUB_RUN_COUNT => self.subscribe_run_count(data, reply),
            _ => Err(IpcStatusCode::Failed),
        };

        self.active_counter.decrement();
        match res {
            Ok(_) => 0,
            Err(e) => e as i32,
        }
    }
}

