impl Manager {
    fn send_request(&self, mut parcel: MsgParcel, ipc_code: IpcCode) -> Result<MsgParcel> {
        let mut reply = self
            .remote
            .send_request(ipc_code as u32, &mut parcel)
            .map_err(ipc_err_handle)?;
        let status: i32 = reply.read().map_err(ipc_err_handle)?;
        if status != IPC_SUCCESS {
            return Err(ipc_err_handle(status));
        }
        Ok(reply)
    }
}

