use ylong_io::UdpSocket;

let sender_addr = "127.0.0.1:8081".parse().unwrap();
let receiver_addr = "127.0.0.1:8082".parse().unwrap();

let sender = UdpSocket::bind(sender_addr)?;
let receiver = UdpSocket::bind(receiver_addr)?;
let connected_sender = sender.connect(receiver_addr)?;
let connected_receiver = receiver.connect(sender_addr)?;

connected_sender.send(b"ping")?;
let mut buf = [0_u8; 32];
let len = connected_receiver.recv(&mut buf)?;
assert_eq!(&buf[..len], b"ping");

pub(crate) struct TcpSocket {
    socket: c_int,
}

impl TcpSocket {
    pub(crate) fn new_socket(addr: SocketAddr) -> io::Result<TcpSocket> {
        if addr.is_ipv4() {
            TcpSocket::create_socket(AF_INET, SOCK_STREAM)
        } else {
            TcpSocket::create_socket(AF_INET6, SOCK_STREAM)
        }
    }

    pub(crate) fn bind(&self, addr: SocketAddr) -> io::Result<()> {
        let (raw_addr, addr_length) = socket_addr_trans(&addr);
        syscall!(bind(self.socket, raw_addr.as_ptr(), addr_length))?;
        Ok(())
    }

    pub(crate) fn connect(self, addr: SocketAddr) -> io::Result<TcpStream> {
        let stream = TcpStream { inner: unsafe { net::TcpStream::from_raw_fd(self.socket) } };
        let (raw_addr, addr_length) = socket_addr_trans(&addr);
        syscall!(connect(self.socket, raw_addr.as_ptr(), addr_length)).ok();
        Ok(stream)
    }
}

use std::time::Duration;
use ylong_io::TcpStream;

let addr = "127.0.0.1:1234".parse().unwrap();
let mut buffer = [0_u8; 1024];
let mut stream = TcpStream::connect(addr)?;

loop {
    std::thread::sleep(Duration::from_micros(300));
    if stream.read(&mut buffer).is_ok() {
        break;
    }
