use ipc_rust::{BorrowedMsgParcel, IRemoteBroker, IpcResult, define_remote_object};

pub trait ICalc: IRemoteBroker {
    fn add(&self, num1: i32, num2: i32) -> IpcResult<i32>;
}

fn on_icalc_remote_request(
    stub: &dyn ICalc,
    code: u32,
    data: &BorrowedMsgParcel,
    reply: &mut BorrowedMsgParcel,
) -> IpcResult<()> {
    let num1: i32 = data.read()?;
    let num2: i32 = data.read()?;
    let ret = stub.add(num1, num2)?;
    reply.write(&ret)?;
    Ok(())
}

define_remote_object!(
    ICalc["example.calc.ipc.ICalcService"] {
        stub: CalcStub(on_icalc_remote_request),
        proxy: CalcProxy,
    }
);

define_remote_object!(
    IDeviceStatus["ohos.msdp.Idevicestatus"] {
        stub: FusionIpcStub(on_remote_request),
        proxy: FusionIpcProxy,
    }
);

